<?php declare(strict_types=1); require __DIR__.'/bootstrap.php'; use App\Auth; if (Auth::check()) { header('Location: /'); exit; } $error=null; if ($_SERVER['REQUEST_METHOD']==='POST') { if (Auth::login(trim($_POST['username']??''),(string)($_POST['password']??''))) { header('Location: /'); exit; } $error='Usuário ou senha inválidos.'; } ?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login · Telegram Router</title><link rel="stylesheet" href="/assets/app.css"></head><body class="auth"><form class="card auth-card" method="post"><h1>Telegram Media Router</h1><p class="muted">Painel protegido</p><?php if($error): ?><div class="error"><?=htmlspecialchars($error)?></div><?php endif; ?><label>Usuário<input name="username" required autofocus></label><label>Senha<input name="password" type="password" required></label><button>Entrar</button></form><script src="/assets/toast.js" defer></script></body></html>
